async function main() {
  console.log("Upserting languages...");
  for (const lang of LANGUAGES) {
    await prisma.language.upsert({
      where: { code: lang.code },
      update: { name: lang.name, nativeName: lang.nativeName, flag: lang.flag, active: true },
      create: { code: lang.code, name: lang.name, nativeName: lang.nativeName, flag: lang.flag, active: true, sortOrder: lang.sortOrder },
    });
  }

  console.log("Upserting translations...");
  let count = 0;
  for (const [key, values] of Object.entries(T)) {
    for (const lang of LANGUAGES) {
      const value = values[lang.code];
      if (!value) continue;
      await prisma.translation.upsert({
        where: { key_languageCode: { key, languageCode: lang.code } },
        update: { value },
        create: { key, languageCode: lang.code, value },
      });
      count++;
    }
  }
  console.log(`Done. ${Object.keys(T).length} keys x ${LANGUAGES.length} languages = ${count} translation rows upserted.`);
}

main()
  .catch((e) => { console.error(e); process.exit(1); })
  .finally(() => prisma.$disconnect());
